'QZ_Setup_Title' => 'Sådan opsætter du QZ Tray-udskrivning (én gang på hver computer, der udskriver etiketter)',
'QZ_Step_Install' => '1. Installer QZ Tray på denne computer — download det gratis fra qz.io, start det og lad det køre (det ligger i systembakken på Windows eller i menulinjen på macOS).',
'QZ_Step_Connect' => '2. Tilslut din etiketprinter via USB, og kontroller, at den er installeret i styresystemet (Windows: Indstillinger > Printere og scannere — macOS: Systemindstillinger > Printere og scannere).',
'QZ_Step_Detect' => '3. Klik på knappen ⟳ ud for "Printernavn" ovenfor for at finde printerne på denne computer, og vælg derefter din etiketprinter. Lad feltet være tomt for at bruge computerens standardprinter.',
'QZ_Step_Cert' => '4. For at udskrive uden tilladelses-pop op skal du downloade certifikatet nedenfor og kopiere det til QZ Trays installationsmappe, omdøbt til override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Afslut derefter QZ Tray, og start det igen.',
'QZ_Step_Test' => '5. Klik på "Udskriv testetiket" nedenfor. Hvis QZ Tray beder om tilladelse, så klik på Tillad — med certifikatet installeret spørger det ikke igen.',
'QZ_Step_Save' => '6. Klik på Send for at gemme disse indstillinger. Etiketter fra siden Udskriv stregkode udskrives nu direkte på denne printer uden browserens udskriftsdialog.',
'QZ_Setup_Note' => 'QZ Tray kører på den computer, du browser fra, så det virker, selv når Stocky hostes på en fjernserver. Alle computere, der udskriver etiketter, skal have QZ Tray installeret.',

