'Label_Render_Mode' => 'Etiketgengivelse',
'Label_Render_Mode_Hint' => 'Hvordan etiketten tegnes. Printerskrifttyper er hurtigst og giver den skarpeste stregkode, men udskriver kun almindelige latinske tegn i printerens egen skrifttype. Forhåndsvisningsbillede gengiver dit etiketdesign nøjagtigt — din valgte skrifttype, ethvert sprog — sådan som dedikeret etiketsoftware gør.',
