'Label_Height_Mm' => 'Etikethøjde (mm)',
'Label_Size_Hint' => 'Den fysiske størrelse på én etiket på rullen. Den skal svare nøjagtigt til de ilagte etiketter — en forkert størrelse får printeren til at lede efter mellemrummet det forkerte sted, så hver etiket udskrives længere ude af position.',
'Calibrate_Labels' => 'Kalibrer etiketter',
