'Dpi_Test_Sent' => 'To etiketter udskrives, mærket 203 og 300. Den korrekte viser et komplet rektangel med en lille, ens margen på alle fire sider — sæt "Printhovedets opløsning" til det tal, og gem.',
'Label_Offset_X' => 'Vandret forskydning (mm)',
'Label_Offset_X_Hint' => 'Flytter udskriften sidelæns på etiketten. Bruges, når tekst skæres af i den ene side — f.eks. 2,5, når den hvide etiket sidder centreret på et bredere bagpapir. Juster i trin på 0,5.',
'Label_Offset_Y' => 'Lodret forskydning (mm)',
