/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Ordrevejledning',
'Ord_Guide_Intro' => 'Sådan bevæger en ordre afgivet i din webshop sig ind i din lagerbeholdning og dit regnskab, og hvor pengene faktisk registreres.',
'Ord_Guide_Lifecycle_Title' => 'Ordrestatus',
'Ord_Guide_Lifecycle_Pending' => 'En ny ordre, der afventer din gennemgang. Kun en afventende ordre kan bekræftes eller annulleres.',
'Ord_Guide_Lifecycle_Confirmed' => 'Du har accepteret ordren. Stocky opretter et salg på det lager, du valgte, og trækker lagerbeholdningen — det salg er den post, som dine lager-, betalings- og fortjenesterapporter læser fra.',
'Ord_Guide_Lifecycle_Shipped' => 'Du har afsendt ordren. Kun ekspedition: lagerbeholdningen blev allerede trukket, da du bekræftede.',
'Ord_Guide_Lifecycle_Delivered' => 'Kunden har modtaget ordren. Det er dette, der starter returperioden.',
'Ord_Guide_Lifecycle_Cancelled' => 'Ordren blev droppet før bekræftelse, så der blev ikke oprettet noget salg og ikke trukket noget fra lagerbeholdningen.',
'Ord_Guide_PaymentStatus_Tip' => 'Angives ved betaling og kan ikke redigeres her. Klik for at se, hvordan betalingen registreres.',
'Ord_Guide_Payment_Title' => 'Betalingsstatus',
'Ord_Guide_Payment_Intro' => 'Denne kolonne registrerer, hvordan kunden valgte at betale ved kassen. Den angives af webshoppen og kan ikke redigeres fra denne side — selve pengene spores på det salg, der oprettes, når ordren bekræftes.',
'Ord_Guide_Payment_Paid' => 'Kunden har allerede betalt online via en betalingsgateway. Når ordren bekræftes, oprettes salget som Betalt, og betalingen registreres for dig — du skal ikke gøre andet.',
'Ord_Guide_Payment_Pending' => 'Efterkrav, bankoverførsel eller en anden betal-senere-metode. Når ordren bekræftes, oprettes salget som Ubetalt, så du selv registrerer pengene, når du har modtaget dem — se trinene nedenfor.',
'Ord_Guide_Payment_Failed' => 'Gatewayen afviste betalingen, eller kunden afbrød den. Ordren annulleres automatisk.',
'Ord_Guide_MarkPaid_Title' => 'Ændring af en betaling fra afventende til betalt',
'Ord_Guide_MarkPaid_Step1' => 'Bekræft ordren her først — det er bekræftelsen, der opretter salget.',
'Ord_Guide_MarkPaid_Step2' => 'Åbn Salg > Alle salg, og find salget (samme kunde, og detaljesiden viser den onlineordre, det stammer fra).',
'Ord_Guide_MarkPaid_Step3' => 'Åbn rækkens handlingsmenu, og vælg Opret betaling.',
'Ord_Guide_MarkPaid_Step4' => 'Indtast beløbet, betalingsmetoden og datoen, og gem. Salget skifter selv til Delvis eller Betalt afhængigt af beløbet.',
'Ord_Guide_MarkPaid_Note' => 'Betalingsstatussen, der vises her, registrerer fortsat valget ved kassen og forbliver uændret. Salget er regnskabsposten, og det er det, der fodrer dine betalings- og fortjenesterapporter. Brug Vis betalinger på salget for at gennemse eller redigere det, du har indtastet.',
'Ord_Guide_Notes_Title' => 'Godt at vide',
'Ord_Guide_Note_Warehouse' => 'Det lager, du vælger ved bekræftelsen, afgør, hvorfra lagerbeholdningen tages. Lagre, der ikke kan dække hele ordren, er markeret som Udsolgt på listen.',
'Ord_Guide_Note_Preorder' => 'Forudbestillingsvarer springer lagerkontrollen over, så en ordre med dem kan bekræftes, selv når antallet endnu ikke er på lager.',
'Ord_Guide_Note_Flagged' => 'Et Markeret-mærke betyder, at ordren udløste en svindelkontrol ved kassen. Hold musen over mærket for at se årsagen, og gennemgå ordren, før du bekræfter den.',
'Ord_Guide_Note_Cancel' => 'Annullering er kun mulig, mens ordren stadig afventer. Når den er bekræftet, skal den i stedet tilbageføres via salget eller en kunderetur.',


