'VG_Rows_Text' => 'Hver række har billede, kode, stregkode, kostpris, pris, engrospris og minimumssalgspris. Når du opretter et produkt, kan du også indtaste startlagerbeholdningen pr. lager for hver variant. Mærket "Ufuldstændig" betyder, at rækken mangler en værdi for en valgmulighed.',
'VG_List_Title' => 'Tilstand med enkel liste',
'VG_List_Text' => 'Skriv et variantnavn og tryk Enter (eller klik på Tilføj) for at tilføje en række, og udfyld derefter kode og priser. Dette er den klassiske funktionsmåde, og den forbliver tilgængelig for eksisterende produkter.',
'VG_Edit_Title' => 'Redigering senere',
'VG_Edit_1' => 'Tilføj en værdi og klik på "Generér varianter": kun de manglende kombinationer tilføjes. Eksisterende rækker beholder deres koder, priser og historik.',
'VG_Edit_2' => 'Fjernes en værdi eller en valgmulighed, fjernes de rækker, der bruger den. Rækker, der allerede er gemt, slettes efter en bekræftelse, når du gemmer produktet.',
'VG_Edit_3' => 'En variant, der stadig har lagerbeholdning, kan ikke fjernes. Regulér eller overfør først lagerbeholdningen.',
'VG_Edit_4' => 'Skift til "Enkel liste" bevarer rækkerne og deres navne, men fjerner definitionerne af valgmuligheder.',
'VG_Store_Title' => 'I webbutikken',
'VG_Store_Text' => 'Kunderne vælger én værdi pr. valgmulighed, for eksempel Farve og derefter Størrelse. Kombinationer, der ikke findes, er deaktiveret, og udsolgte er overstreget. Det er den valgte variant, der lægges i kurven.',
