'Set_Sidebar_Intro_Title' => 'Træk og slip for at omarrangere sidemenuen',
'Set_Sidebar_Intro_Desc' => 'Omarranger moduler, omarranger elementer i et modul, eller træk et element til et andet modul. Moduler forbliver altid på øverste niveau, og elementer kan ikke blive til moduler. Den gemte opstilling gælder for alle brugere.',
