'Upd_Note_Code_Changes_Lost' => 'Bemærk 1: Hvis du har foretaget ændringer i koden manuelt, vil dine ændringer gå tabt.',
'Upd_Manual_Steps_Intro' => 'Følg disse trin for at opdatere din applikation',
'Upd_Note_Permission_Only' => 'Bemærk 2: kun en administrator eller en bruger med rettigheden "{perm}" kan opgradere systemet',
'Upd_Manual_Step_Backup_Db' => 'Tag en backup af din database. Gå til {backup}, klik på Opret backup — du finder den i {path} — eller eksportér din database fra PhpMyAdmin og gem den på din pc.',
'Upd_Manual_Step_Backup_Files' => 'Tag en backup af dine filer før opdateringen.',
'Upd_Manual_Step_Download' => 'Download den nyeste version fra din CodeCanyon-konto, og udpak den.',
'Upd_Manual_Step_Remove' => 'Fjern de tidligere filer, {except}:',
'Upd_Except' => 'undtagen',
'Upd_File_Label' => 'fil: {name}',
'Upd_Folder_Label' => 'mappe: {name}',
'Upd_Manual_Step_Reupload' => 'Upload filerne og mapperne fra den nye opdatering igen, {except} de samme tre stier ovenfor.',
'Upd_Manual_Step_Visit' => 'Besøg {url} for at opdatere din database.',
'Upd_Manual_Step_Clear_Cache' => 'Ryd din browsers cache fuldstændigt.',
'Upd_Manual_Step_Done' => 'Så er du færdig! God fornøjelse med den opdaterede applikation.',
'Upd_Note_Blank_Pages' => 'Bemærk: Hvis nogle sider ikke indlæses eller er tomme, så sørg for, at du har ryddet din browsers cache.',
'Upd_Guide_Before_Title' => '1. Før du opdaterer',
'Upd_Guide_Before_Download' => 'Download {package} af applikationen fra din CodeCanyon-konto ({path}). Udpak den ikke — opdateringsværktøjet skal bruge ZIP-filen præcis som downloadet.',
'Upd_Latest_Full_Zip' => 'den nyeste fulde ZIP-pakke',
'Upd_Guide_Before_Admin' => 'Sørg for, at du er logget ind som en administrator med rettigheden {perm}. Ingen andre kan se eller køre opdateringsværktøjet.',
'Upd_Guide_Before_Quiet' => 'Vælg et roligt tidspunkt: under opdateringen skifter applikationen kortvarigt til vedligeholdelsestilstand, og andre brugere lukkes ude.',
'Upd_Guide_Before_No_Manual' => 'Du behøver {not} at tage backup manuelt, udpakke filer, køre kommandoer, redigere konfigurationsfiler eller røre databasen — opdateringsværktøjet gør alt dette automatisk. (En ekstra manuel backup skader selvfølgelig aldrig.)',
'Upd_Not' => 'ikke',
'Upd_Guide_Code_Overwritten' => 'Hvis du har ændret applikationens kode manuelt, overskrives dine ændringer af opdateringen. Dine data, uploads, indstillinger og .env bevares altid.',
'Upd_Guide_Running_Title' => '2. Kørsel af opdateringen',
'Upd_Guide_Run_Open' => 'Åbn {path} (denne side), og bliv på fanen {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: klik eller træk den downloadede pakke ind i uploadfeltet. Store filer uploades i små bidder, så dette virker også på delt hosting med lave uploadgrænser. En kontrolsum beskytter mod beskadigede eller ufuldstændige uploads.',
'Upd_Upload_The_Zip' => 'Upload ZIP-filen',
'Upd_Guide_Run_Validation' => '{auto} efter uploaden (du kan køre den igen med knappen {button}). Systemet kontrollerer: ZIP-integritet, pakkestruktur og fuldstændighed, versionskompatibilitet (nedgraderinger afvises), påkrævet PHP-version og udvidelser, filrettigheder, ledig diskplads, databaseforbindelse, konfiguration, og at ingen anden opdatering kører.',
'Upd_Validation_Runs_Automatically' => 'Validering kører automatisk',
'Upd_Guide_Run_Review' => 'Gennemgå panelet {panel}. Knappen {button} vises kun, når alle kritiske kontroller er bestået. Hvis en kontrol fejler, fortæller meddelelsen dig præcis, hvad der skal rettes.',
'Upd_Guide_Run_Click' => 'Klik på {button}, og bekræft. Derefter skal du blot {keep} og følge statuslinjen. Systemet udfører i rækkefølge:',
'Upd_Keep_Page_Open' => 'holde denne side åben',
'Upd_Guide_Phase_Backup' => '{label} — et fuldt databasedump, en ZIP af alle applikationsfiler, som opdateringen kan ændre, og en kopi af {env} oprettes og {verified}. Dine uploads ({images}) og {storage} røres aldrig af en opdatering, så de arkiveres ikke. Hvis en backup ikke kan oprettes, stopper opdateringen her, og intet ændres.',
'Upd_Verified' => 'verificeres',
'Upd_Guide_Phase_Prepare' => '{label} — den nye version udpakkes til et klargøringsområde og valideres igen. Den kørende applikation er stadig urørt.',
'Upd_Guide_Phase_Maintenance' => '{label} — vedligeholdelsestilstand aktiveres; besøgende ser en venlig "Vi er snart tilbage"-skærm.',
'Upd_Guide_Phase_Files' => '{label} — de nye filer skiftes ind næsten øjeblikkeligt; de gamle filer gemmes til tilbagerulning. Beskyttede stier ({env}, {storage}, {images}) erstattes aldrig.',
'Upd_Guide_Phase_Database' => '{label} — migreringer køres, hvorefter rettigheder, oversættelser og skabeloner opdateres.',
'Upd_Guide_Phase_Cache' => '{label} — alle caches ryddes og genopbygges.',
'Upd_Guide_Phase_Verify' => '{label} — sundhedstjek bekræfter, at den nye version starter, databasen virker, alle migreringer er kørt, og konfigurationen er gyldig.',
'Upd_Guide_Phase_Done' => '{label} — vedligeholdelsestilstand ophæves, og midlertidige filer ryddes op.',
'Upd_Guide_Run_Success' => 'Når du ser {success}, så klik på {reload}, og genindlæs din browser fuldstændigt ({keys}), så de nye ressourcer til administrationspanelet indlæses.',
'Upd_Update_Successful_Short' => 'Opdatering gennemført',
'Upd_Guide_No_Internet' => 'Der kræves ingen internetforbindelse under opdateringen — alt kommer fra den uploadede ZIP-fil. Hvis du mister forbindelsen eller lukker browseren, ødelægger det IKKE opdateringen: serveren husker præcis, hvor den stoppede.',
'Upd_Guide_Wrong_Title' => '3. Hvis noget går galt',
'Upd_Guide_Wrong_Rollback' => '{label} — hvis noget fejler, efter at filerne er begyndt at blive ændret (udpakningsfejl, migreringsfejl, mislykket sundhedstjek, fuld disk, …), gendanner systemet automatisk de tidligere filer og databasen fra den verificerede backup, ophæver vedligeholdelsestilstand og rapporterer {message}. Du ender præcis, hvor du startede.',
'Upd_Automatic_Rollback' => 'Automatisk tilbagerulning',
'Upd_Failed_Previous_Restored' => 'Opdatering mislykkedes — tidligere version gendannet',
'Upd_Guide_Wrong_Interrupted' => '{label} (servergenstart, timeout, lukket browser, strømsvigt) — når du åbner denne side igen, tilbyder et rødt banner to sikre valg: {resume} (fortsætter fra præcis det trin, hvor den stoppede) eller {rollback} (gendanner den tidligere version fra backuppen).',
'Upd_Interrupted_Update' => 'Afbrudt opdatering',
'Upd_Guide_Wrong_Unreachable' => '{label} — brug den selvstændige {console} på {path}. Den virker, selv mens webstedet er i vedligeholdelsestilstand, eller ressourcerne til administrationspanelet er ødelagte, og tilbyder de samme handlinger Fortsæt / Rul tilbage. Der er også et diskret link "Administratoradgang" nederst på vedligeholdelsesskærmen.',
'Upd_Admin_Unreachable' => 'Administrationspanelet kan ikke nås',
'Upd_Recovery_Console' => 'gendannelseskonsol',
'Upd_Guide_Wrong_Locked_Out' => '{label} — mens en opdatering kører, viser denne side et {link}. Gem det, hvis du får brug for at komme ind igen (f.eks. efter din session er udløbet); det lukker dig forbi vedligeholdelsesskærmen, så du kan logge ind igen.',
'Upd_Locked_Out_Maintenance' => 'Lukket ude af vedligeholdelsestilstand',
'Upd_Bypass_Link' => 'omgåelseslink',
'Upd_Guide_Wrong_Concurrent' => '{label} — vedkommende ser {message} Der kan kun køre én opdatering ad gangen.',
'Upd_Another_Admin_Updating' => 'En anden administrator forsøger at opdatere samtidig',
'Upd_Guide_Backups_Title' => '4. Backups & gendannelse',
'Upd_Guide_Backups_Created' => 'Hver opdatering opretter en backup, {before} noget røres: alle applikationsfiler, som opdateringen kan erstatte, en kopi af {env} og et fuldt databasedump. Uploads og {storage} ændres aldrig af en opdatering og er derfor ikke en del af den — tag dine egne backups af dem. Backups ligger i {path} og er aldrig tilgængelige fra nettet.',
'Upd_Before' => 'før',
'Upd_Guide_Backups_Panel' => 'Panelet {panel} på fanen {tab} viser dem med dato, version og størrelse. Derfra kan du {restore} enhver komplet backup (filer + database — der tages først en sikkerhedskopi af den aktuelle database) eller {delete} gamle.',
'Upd_Restore_Verb' => 'gendanne',
'Upd_Delete_Verb' => 'slette',
'Upd_Guide_Backups_Retention' => 'Brug {keep} til at vælge, hvor mange backups der beholdes; ældre fjernes automatisk efter hver vellykket opdatering. Den eneste tilbageværende komplette backup kan aldrig slettes — du har altid en vej tilbage.',
'Upd_Guide_Manual_Title' => '5. Manuel opdatering (alternativ metode)',
'Upd_Guide_Manual_Text' => 'Hvis du foretrækker at opdatere manuelt, eller uploaderen ikke kan bruges på din server, så følg trin-for-trin-vejledningen på fanen {tab} på denne side.',
'Upd_Guide_Clear_Cache_First' => 'Hvis sider ser ødelagte eller tomme ud efter en opdatering, så ryd først din browsers cache — det er næsten altid årsagen.',
'Upd_Restore_Backup_Confirm' => 'Gendan denne backup? Nuværende filer og den nuværende database erstattes af backuppen. Der tages først en sikkerhedskopi af den nuværende database. (v{version} — {date})',
'Woo_Guide_Lead' => 'Sådan holder en WooCommerce-butik sig i takt med ERP\'en. Cron-linjerne nedenfor er bygget til denne server, så de kan kopieres direkte over på den.',
'Woo_Guide_Ways_Note' => 'I modsætning til Shopify sender WooCommerce intet til ERP\'en af sig selv — der er ingen webhook-modtager her, så alt, der kommer {in}, ankommer efter tidsplanen. Kun lagerbeholdning, der går {out}, kan være øjeblikkelig.',
'Woo_In' => 'ind',
'Woo_Out' => 'ud',
'Woo_Guide_Both_Ways_Title' => 'Begge veje kræver dette først',
'Woo_Api_Keys' => 'API-nøgler',
'Woo_Guide_Api_Keys_Text' => '{path}, rettighed {perm}. Kopiér consumer key og secret til fanen {settings} sammen med butikkens URL — dit websteds adresse uden afsluttende skråstreg, f.eks. {example}.',
'Woo_Credentials_Saved' => 'loginoplysninger gemt',
'Woo_Not_Configured_Yet' => 'ikke konfigureret endnu',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress-applikationsadgangskode (valgfri)',
'Woo_Guide_Wp_App_Password_Text' => 'Bruges kun til produktbilleder. WooCommerce-API\'en flytter produkter, lagerbeholdning, kategorier, mærker, kunder og ordrer; WordPress-API\'en er det, der søger i mediebiblioteket og uploader et billede, der ikke findes der endnu.',
'Woo_Guide_Wp_App_Password_Note' => 'Brug en WordPress-bruger, der kan administrere medier, og opret adgangskoden under {path}. Lad begge felter være tomme, og alt synkroniseres stadig — kun vedhæftning af billeder springes over.',
'Woo_Guide_Pick_Way_Title' => 'Vælg derefter, hvordan den holdes i takt',
'Woo_Right_Away' => 'Med det samme',
'Woo_Stock_Live' => 'lagerbeholdning live',
'Woo_Stock_Not_Live' => 'lagerbeholdning ikke live',
'Woo_Guide_Realtime_Lead' => 'Kun én retning: lagerbeholdning og produkter, der forlader ERP\'en. Ordrer og produktændringer foretaget i WooCommerce ankommer stadig efter tidsplanen — se den anden fane.',
'Woo_Push_Stock_On_Change' => 'Send lagerbeholdning i det øjeblik, den ændres',
'Woo_Setting_People_Miss' => 'Det er denne indstilling, folk overser',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Et POS-salg når {not} WooCommerce af sig selv. Er den slået fra, opdager butikken det først ved næste lagersynkronisering — som standard en time — og i det tidsrum kan den sælge en enhed, du allerede har solgt ved kassen.',
'Woo_Does_Not' => 'ikke',
'Woo_Guide_Tick_Instant' => 'Markér {option} på fanen {settings}. Det er hele opsætningen — ingen worker, ingen cron. Hvert salg, hver retur, regulering, overførsel og hvert modtaget køb sender derefter kun de pågældende produkter, lige efter at salget er gemt, og et salg med tyve linjer koster én afsendelse, ikke tyve. Kassen venter aldrig på det.',
'Woo_Currently' => 'Aktuelt:',
'Woo_Instant_On_Text' => 'til — lagerbeholdning sendes ved ændring',
'Woo_Instant_Off_Text' => 'fra — lagerbeholdning kun efter tidsplanen',
'Woo_Guide_Instant_Note' => 'Kun produkter, der allerede er knyttet til WooCommerce, sendes — et produkt, der aldrig er blevet synkroniseret, har intet i butikken at rette. Variable produkter sendes via deres overordnede produkt, og et kombiprodukt sendes igen, når en af dets komponenter ændres. Masseoperationer (sletning af et produkt, nulstilling af et lager) skriver lagerbeholdning uden at udløse en hændelse, hvilket er én grund til også at beholde den timevise lagersynkronisering.',
'Woo_Push_Products_On_Save' => 'Send produkter i det øjeblik, de gemmes',
'Woo_Guide_Tick_Auto_Products' => 'Markér {option} på fanen {settings}, så sendes et produkt, der oprettes, redigeres eller duplikeres i Stocky, til WooCommerce lige efter, at det er gemt — detaljer, pris, varianter og billeder, derefter lagerbeholdningen. Et nyt produkt oprettes i butikken med det samme i stedet for at vente på den natlige produktsynkronisering.',
'Woo_On' => 'til',
'Woo_Off' => 'fra',
'Woo_Guide_Bulk_Imports_Note' => 'Masseimporter sendes ikke én ad gangen — kør en produktsynkronisering efter en import. Synkronisér kategorier og mærker først, så et afsendt produkt havner i den rigtige kategori.',
'Woo_Nothing_Else_To_Install' => 'Intet andet at installere',
'Woo_Guide_Same_Process' => 'Ingen kø-worker, ingen cron-post. Afsendelsen kører i samme proces, som betjente salget, {after} svaret er sendt tilbage, så kassen aldrig venter på WooCommerce. Afsendelser overlapper aldrig: ændringer foretaget, mens én kører, venter på den og sendes lige bagefter.',
'Woo_After' => 'efter',
'Woo_Guide_Shop_Stops_Answering' => 'En butik, der holder op med at svare, opgives efter otte sekunder, og afsendelser sættes på pause i fem minutter, så hvert salg ikke skal vente på den igen; de ændringer, der kom ind i mellemtiden, sendes med den første afsendelse efter pausen, og den timevise lagersynkronisering indhenter under alle omstændigheder. Hver pause registreres på fanen Logfiler.',
'Woo_Guide_Artisan_Exception' => 'Én undtagelse: en lagerændring foretaget af en artisan-kommando har intet svar at komme efter, så den sættes i stedet i kø på {queue}. For også at få dem sendt hurtigt, så tøm den kø:',
'Woo_Cron_Line_Copied' => 'Cron-linje kopieret',
'Woo_Command_Copied' => 'Kommando kopieret',
'Woo_Guide_Not_Woo_Queue' => 'Bevidst ikke køen {queue}: den bærer de timelange katalogbatches, og en øjeblikkelig afsendelse i kø bag en af dem ville ikke være øjeblikkelig.',
'Woo_On_A_Schedule' => 'Efter en tidsplan',
'Woo_Guide_Scheduled_Lead' => 'Alt kontrolleres igen med jævne mellemrum, begge veje. Det er sådan, ordrer når ERP\'en, sådan et katalog udgives, og det reparerer alt, som den hurtige vej overså. Hvert job har sin egen cron-post, så du kun kører det, du ønsker.',
'Woo_Guide_Sync_Drains_Queue' => '{command} tømmer sin egen kø, mens den kører, så disse linjer behøver ingen separat worker. På Windows skal du bruge Opgavestyring med programmet {program} og de samme argumenter, startet i {path}.',
'Woo_Or_No_Cron' => 'Eller slet ingen cron',
'Woo_Guide_No_Cron_Text' => 'Hver fane her synkroniserer efter behov, og en manuel synkronisering tømmer sine egne batches, mens siden er åben — så en lille butik kan køre helt uden cron-post. Det, du mister, er alt, hvad der sker, mens ingen kigger: ordrer ankommer kun, når nogen trykker på knappen.',
'Woo_Commands_Worth_Knowing' => 'Kommandoer, der er værd at kende',
'Woo_Worth_Knowing' => 'Værd at vide',
'Woo_Guide_Changing_Url_Clears' => 'Ændring af butikkens URL eller API-nøglerne rydder alle tilknytninger — produkter, kategorier, mærker og kunder synkroniseres alle igen til den nye butik.',
'Woo_Guide_Keep_Skus' => 'Hold SKU\'er ensartede mellem Stocky og WooCommerce: det er det, der forhindrer dubletter, og det, der gør gentilknytning sikker.',
'Woo_Guide_Stock_Total' => 'Lagerbeholdningen, der udgives til Woo, er den {total}, ikke ét lagers tal.',
'Woo_Total_Across_Warehouses' => 'samlede beholdning på tværs af alle lagre',
