'Woo_Settings_Instant_Hint' => 'Et salg, en retur eller en regulering sender lagerbeholdningen for netop de produkter i det øjeblik, den gemmes, så butikken er korrekt inden for sekunder i stedet for ved næste timevise lagersynkronisering. Intet andet at installere — afsendelsen kører, efter at salget er besvaret, så kassen aldrig venter på WooCommerce. Mere på fanen {guide}.',
