'Jumia_Push_Prices_Stock_Title' => 'Send priser og lagerbeholdning til Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Sender den aktuelle pris og det aktuelle antal for hvert produkt (og hver variant), der har en SKU, som matcher Jumia-opslagets {sku}. Opdateringer indsendes som Seller Center-feeds og anvendes asynkront — feed-ID\'et registreres på fanen Logs, og afvisninger pr. vare vises på Seller Centers skærm for feedstatus.',
'Jumia_Push_Prices_Stock' => 'Send priser og lagerbeholdning',
