'Jumia_Guide_3' => 'Sørg for, at hvert Jumia-opslags {sku} er lig med Stocky-produktkoden — det er den identitet, der bruges både til afsendelse af lagerbeholdning og matchning af ordrer.',
'Jumia_Guide_4' => 'Send priser og lagerbeholdning efter ændringer i lageret; hent ordrer regelmæssigt (Jumia har ingen webhooks i dette API).',
'Jumia_Guide_5' => 'Oprettelse af nye opslag foregår fortsat i Seller Center — Jumia kræver kategorispecifikke attributter og billedgennemgang, som kun deres portal håndterer godt.',
