'Shopify_Could_Not_Remove_Sub' => 'Kunne ikke fjerne abonnementet',
'Shopify_Could_Not_Load_Store' => 'Kunne ikke indlæse denne butik',
'Shopify_G_Lead_Store' => 'Hvad denne butik skal bruge for at holde sig synkroniseret. Alt her er specifikt for denne butik — stierne og id\'erne er rigtige, så kommandoerne kan kopieres direkte over på serveren.',
'Shopify_G_Lead_Generic' => 'Sådan holder en Shopify-butik sig synkroniseret med ERP-systemet. Vælg en butik ovenfor for at se dens egen tilstand, eller læs det, som det er — cron-linjen og webhook-URL\'en er de samme, uanset hvilken butik du forbinder.',
'Shopify_G_Ways_Note' => 'De fleste butikker kører begge: den første holder butikken opdateret minut for minut, den anden fanger alt, hvad den første gik glip af — en webhook, der aldrig nåede frem, en ændring foretaget direkte i Shopify-administrationen, en nat hvor siden var nede.',
'Shopify_G_Both_Need' => 'Begge metoder kræver dette først',
'Shopify_G_Credentials' => 'Shopify-legitimationsoplysninger',
'Shopify_G_Cred_Intro' => 'Siden januar 2026 opretter Shopify ikke længere brugerdefinerede apps i administrationen, så der er to slags forbindelser:',
'Shopify_G_Cred_DevDash' => '{app} (enhver butik, der forbindes nu) — {path}. Tildel de Admin API-scopes, som denne butik synkroniserer, installer appen i butikken, og kopiér derefter {clientId} og {clientSecret} fra appens indstillingsside til {where}. ERP-systemet bytter dem selv til et adgangstoken og fornyer det, før det udløber hver 24. time. Client secret signerer også webhooks, så der kræves ikke andet. Appen og butikken skal ligge i den samme Shopify-organisation.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard-app',
'Shopify_G_Cred_Legacy' => '{app} (oprettet i administrationen før 2026) — fungerer fortsat uændret med sit {token} ({prefix}) og sin {secret} som webhook-signeringsnøgle. Det er ikke den samme værdi som tokenet, og at bytte rundt på dem er den almindelige årsag til, at webhooks afvises.',
'Shopify_G_Legacy_App' => 'Ældre brugerdefineret app',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'gemt',
'Shopify_G_Missing_Refused' => 'mangler — leveringer vil blive afvist',
'Shopify_G_Where_Data_Desc' => '{path} ERP-lageret, hvis lagerbeholdning denne butik sælger, og den Shopify-lokation, som lagerbeholdningen skrives til. Både lagersynkronisering og ordreimport nægter at køre uden dem.',
'Shopify_G_Currently' => 'Aktuelt: lager {warehouse}, lokation {location}',
'Shopify_G_Not_Set_Lower' => 'ikke angivet',
'Shopify_G_Ready' => 'klar',
'Shopify_G_Incomplete' => 'ufuldstændig',
'Shopify_G_Manual_Syncs' => 'Synkroniseringer, du starter manuelt',
'Shopify_G_Manual_Desc' => 'En synkronisering startet fra {centre} svarer med det samme og kører i baggrunden i korte bidder, der hver fortsætter, hvor den forrige slap. Et stort katalog bliver aldrig afbrudt halvvejs af hosting, der afslutter lange webforespørgsler (LiteSpeed, nginx, en load balancer), og lukning af siden stopper den ikke. Workeren til det er én cron-linje mere:',
'Shopify_G_Cron_Copied' => 'Cron-linje kopieret',
'Shopify_G_Manual_Note' => 'Uden den bliver en synkronisering stadig færdig, men kun mens Sync Centre-siden er åben: når ingen worker tager en kørsel op inden for få sekunder, fortsætter siden den selv, én kort forespørgsel ad gangen. På Windows bruges Opgavestyring hvert minut: program {program}, argumenter {args}, startet i {dir}.',
'Shopify_G_Then_Pick' => 'Vælg derefter, hvordan den holdes synkroniseret',
'Shopify_G_Right_Away' => 'Med det samme',
'Shopify_G_Stock_Live' => 'lagerbeholdning live',
'Shopify_G_Stock_Not_Live' => 'lagerbeholdning ikke live',
'Shopify_G_Realtime_Lead' => 'Hver ændring sendes, når den sker, på få sekunder. To halvdele, og de er separate kontakter: {webhooks} henter butikkens egne hændelser ind, og {push} sender lagerbeholdning ud.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'øjeblikkelig lageroverførsel',
'Shopify_G_Webhooks_In' => 'Webhooks — butikken → ERP-systemet',
'Shopify_G_Webhooks_Desc' => 'Ordrer, ændringer i ordrestatus samt ændringer af produkter, kunder og lagerbeholdning foretaget i Shopify. Åbn butikken, og tryk på {button} på dens {tab} — det er sikkert at trykke to gange. Shopify sender til:',
'Shopify_G_Webhooks_Tab' => 'fanen Webhooks',
'Shopify_G_Webhooks_Note' => 'Adressen skal kunne nås fra internettet via HTTPS — Shopify leverer ikke til {localhost} eller et {test}-domæne. Hver levering registreres én gang, så Shopifys genforsøg kan ikke oprette en dubletordre, og en mislykket levering kan afspilles igen. Leveringer afvises, indtil signeringsnøglen fra trin 1 er gemt.',
'Shopify_G_Instant_Out' => 'Øjeblikkelig lageroverførsel — ERP-systemet → butikken',
'Shopify_G_Setting_Missed' => 'Det er denne indstilling, folk overser',
'Shopify_G_Pos_Not_Auto' => 'Et POS-salg når {not} Shopify af sig selv. Er den slået fra, opdager butikken det først ved næste lageroverførselstrin — og i det tidsrum kan den sælge en enhed, du allerede har solgt ved kassen.',
'Shopify_G_Not' => 'ikke',
'Shopify_G_Tick_Push' => 'Markér {setting} under {where}. Det er hele opsætningen — ingen worker, ingen cron. Hvert salg, hver retur og hver regulering sender derefter en overførsel af netop de produkter, lige efter salget er gemt, og et salg med tyve linjer koster én overførsel, ikke tyve. Kassen venter aldrig på det.',
'Shopify_G_This_Store' => 'Denne butik:',
'Shopify_G_Push_On' => 'til — lagerbeholdning overføres ved ændring',
'Shopify_G_Push_Off' => 'fra — lagerbeholdning kun efter tidsplan',
'Shopify_G_Push_Note' => 'Kun produkter, der allerede har en Shopify-tilknytning, og kun bevægelser på denne butiks lager, overføres. Masseoperationer — sletning af et produkt, nulstilling af et lager — skriver lagerbeholdning uden at udløse en hændelse, hvilket er én grund til også at beholde det planlagte lagertrin.',
'Shopify_G_Nothing_Install' => 'Intet andet at installere',
'Shopify_G_No_Worker_Note' => 'Ingen af halvdelene kræver en queue worker eller en cron-post. En indgående webhook håndteres i den forespørgsel, Shopify foretager; en udgående lageroverførsel kører i den samme proces, der betjente salget, {after} svaret er sendt tilbage — så kassen venter aldrig på Shopify, og en butik, der holder op med at svare, opgives efter ti sekunder og overlades til næste planlagte lageroverførsel.',
'Shopify_G_After' => 'efter',
'Shopify_G_Artisan_Note' => 'Én undtagelse: en lagerændring foretaget af en artisan-kommando har intet svar at komme efter, så den sættes i kø på {queue} i stedet. Hvis du også vil have dem sendt hurtigt, så tøm den kø:',
'Shopify_G_On_Schedule' => 'Efter tidsplan',
'Shopify_G_On_Lower' => 'til',
'Shopify_G_Off_Lower' => 'fra',
'Shopify_G_Scheduled_Lead' => 'Alt kontrolleres igen med jævne mellemrum, begge veje. Langsommere end realtid, men det er det, der sender lagerbeholdning ud i butikker, der ikke bruger øjeblikkelig overførsel, det, der fanger en mistet webhook, og den eneste måde at flytte et helt katalog på.',
'Shopify_G_Cron_Entry' => 'Cron-posten',
'Shopify_G_Cron_Entry_Desc' => 'Intet planlagt kører uden den. Én linje, kun for dette modul — tilføj den ved siden af det, du ellers har valgt at planlægge:',
'Shopify_G_Cron_Note' => 'Hvert femte minut er den fineste opløsning, en plan kan bruge, fordi fem minutter er det korteste trininterval. En grovere post bliver simpelthen minimum — med {example} kører et trin sat til 5 minutter hvert 15. minut. På Windows bruges Opgavestyring: program {program}, argumenter {args}, startet i {dir}.',
'Shopify_G_Switch_On_Plan' => 'Slå det til, og vælg planen',
'Shopify_G_Plan_Desc' => '{where} Kontakten afgør, om cron overhovedet må handle; planen afgør, hvad den gør. Et {step} er én enhed i én retning med sit eget interval — {first}, {second}. Standardintervallet bruges af ethvert trin, der lader sit eget felt stå tomt.',
'Shopify_G_Step_Lower' => 'trin',
'Shopify_G_Plan_Note' => 'Lad planen stå tom, så henter butikken ordrer og overfører lagerbeholdning med standardintervallet, hvilket de fleste butikker ønsker. Ordrer hentes kun: det er i Shopify, en kunde afgiver dem.',
'Shopify_G_Schedule_On' => 'tidsplan til',
'Shopify_G_Schedule_Off' => 'tidsplan fra — kun manuelt',
'Shopify_G_When_Step_Runs' => 'Hvornår et trin faktisk kører',
'Shopify_G_When_Note' => 'Et trin er forfaldent, når det samme trin sidst {started} for længere tid siden end dets interval, aflæst fra kørselshistorikken. Så en synkronisering, du starter manuelt, udskyder den næste automatiske, og et trin, der bliver ved med at fejle, forsøges igen efter sit interval i stedet for ved hvert tik. Butikkens Oversigt viser hvert trins seneste kørsel, næste forfaldstid og årsagen til, at det er blokeret, når det er. Kør den første katalogoverførsel manuelt — først med {dryRun} — før du sætter den på en tidsplan.',
'Shopify_G_Started_Lower' => 'startede',
'Shopify_G_Where_Setting' => 'Hvor hver indstilling findes',
'Shopify_G_Where_Setting_Note' => 'Alle disse findes på en eksisterende butik: {path}, derefter blyanten (eller {edit} på butikkens egen side).',
'Shopify_G_Product_Images' => 'Produktbilleder',
'Shopify_G_Img_1' => 'Billeder sendes med produktet ved en {push} — hovedbilledet først, derefter galleriet, derefter ét pr. variant, der har sit eget, op til halvtreds.',
'Shopify_G_Products_Push' => 'produktoverførsel',
'Shopify_G_Img_2' => 'En variants billede uploades med produktet og bliver derefter {assigned}, hvilket er sådan Shopify modellerer det: en variant peger på et af produktets billeder. En variant, der genbruger hovedbilledet, uploader det ikke to gange.',
'Shopify_G_Assigned' => 'tildelt den variant',
'Shopify_G_Img_3' => 'Et billede gemt som fil bliver {uploaded} til Shopify, ikke linket, så det virker, selv når denne installation ikke kan nås fra internettet. Et billede tilføjet som indsat link gives til Shopify som den URL, der skal være offentligt tilgængelig.',
'Shopify_G_Uploaded' => 'uploadet',
'Shopify_G_Img_4' => 'De sendes kun igen, når de faktisk ændres — en overførsel, der kun ændrer en pris, lader butikkens billeder være, fordi afsendelse af dem erstatter hele sættet.',
'Shopify_G_Img_5' => 'Fjernelse af et billede i ERP-systemet sletter det {not} i Shopify. Slet det også der, ellers bliver butikken ved med at vise det.',
'Shopify_G_Commands' => 'Kommandoer, der er værd at kende',
'Shopify_G_Command_Copied' => 'Kommando kopieret',
'Shopify_G_Foot' => 'Hver synkronisering skriver til {logs}, og hver butiks Oversigt viser, hvornår hvert trin sidst kørte, hvornår det næste gang er forfaldent, og hvad der blokerer det, når noget gør. Det er der, du først skal kigge, når en synkronisering ikke gjorde, som du forventede.',
'Shopify_G_Covers' => 'Dækker',
'Shopify_G_Covers_Rt' => 'Ordrer og ændringer foretaget i Shopify; lagerbeholdning, der forlader ERP-systemet (et POS-salg, en retur, en regulering)',
'Shopify_G_Covers_Sch' => 'Alt, begge veje — inklusive katalogoverførsler og alt, hvad den hurtige vej gik glip af',
'Shopify_G_Speed' => 'Hastighed',
