'StoreAdm_PG_Intro_Desc' => 'Stripe-nøgler deles globalt (admin og onlinebutik bruger den samme Stripe-integration). Hver fane slår sin metode til eller fra for onlinebutikkens kasse; Offlinebetalinger indeholder de metoder, der betales uden for systemet.',
