'StoreAdm_PG_Paystack_Test_Live' => 'Test eller live afgøres af nøgleparret: {test}-nøgler kører i testtilstand, {live}-nøgler debiterer rigtige kort — der er ingen separat sandbox-kontakt.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook-URL (valgfrit sikkerhedsnet — angiv den under Settings → API Keys & Webhooks i Paystack-dashboardet; forespørgsler HMAC-verificeres med din secret key):',
