'Cr_Guide_Step_Account' => 'Tilføj en fragtfirmakonto',
'Cr_Guide_Step_Account_Help' => 'Vælg dit fragtfirma, og indsæt API-nøglerne fra dets kontrolpanel. Flere konti er fint, for eksempel én pr. lager.',
'Cr_Guide_Step_Test' => 'Test forbindelsen',
'Cr_Guide_Step_Test_Help' => 'Test forbindelse kontrollerer nøglerne og viser ofte de koder, som fragtfirmaets indstillinger beder om.',
'Cr_Guide_Step_Webhook' => 'Registrér webhook-URL\'en',
'Cr_Guide_Step_Webhook_Help' => 'Fragtfirmaer, der sender opdateringer, skal have kontoens webhook-URL (vist nedenfor), så statusser ændres med det samme. De øvrige tjekkes efter en tidsplan.',
'Cr_Guide_Step_Cod' => 'Vælg, hvor efterkravsudbetalinger skal bogføres',
'Cr_Guide_Step_Cod_Help' => 'Vælg i Fragtindstillinger den konto, efterkravsudbetalinger registreres på, og hvordan returnerede pakker og fragtgebyrer håndteres.',
'Cr_Guide_Step_Notify' => 'Giv dine kunder besked',
