'Cr_Guide_Meaning' => 'Betydning',
'Cr_Guide_T_Statuses' => 'Statusser',
'Cr_Guide_Statuses_Note' => 'Statusser går kun fremad, så en forsinket opdatering trækker aldrig en pakke tilbage. En leveret pakke kan stadig meldes som på vej retur eller returneret.',
'Cr_Guide_S_booked' => 'Fragtfirmaet har ordren; ingen har afhentet den endnu. En booking kan kun annulleres nu.',
'Cr_Guide_S_picked_up' => 'Fragtfirmaet har afhentet pakken.',
'Cr_Guide_S_in_transit' => 'Undervejs mellem terminaler, i told eller tilbageholdt.',
'Cr_Guide_S_out_for_delivery' => 'Hos chaufføren i dag.',
'Cr_Guide_S_failed_attempt' => 'Ikke hjemme, afvist eller forkert adresse. Fragtfirmaet prøver igen eller returnerer den.',
'Cr_Guide_S_delivered' => 'Overleveret til kunden. Et efterkravsbeløb bliver registreret som opkrævet af fragtfirmaet.',
'Cr_Guide_S_returning' => 'På vej tilbage til dig.',
'Cr_Guide_S_returned' => 'Tilbage hos dig: den venter i Returer til gennemgang eller lægges automatisk på lager igen.',
'Cr_Guide_S_cancelled' => 'Bookingen blev annulleret.',
'Cr_Guide_T_Booking' => 'Booking af ordrer',
'Cr_Guide_B_Booking' => 'Send til fragtfirma udfylder formularen ud fra salget: modtager, adresse, det udestående beløb som efterkrav og produkternes vægt. Fragtfirmaer med egne bylister viser en vælger, og dit valg huskes for den by. Aggregatorer, DHL, FedEx, UPS og Lalamove tilbyder Sammenlign priser: vælg en pris, og Book køber den. Flere salg kan bookes på én gang fra salgslisten.',
'Cr_Guide_T_Cod' => 'Efterkrav',
'Cr_Guide_B_Cod' => 'En efterkravspakke går fra Ikke opkrævet til Opkrævet af fragtfirma (ved levering) til Udbetalt til dig. Fragtfirmaer, der rapporterer udbetalinger, flytter selv det sidste trin; for de øvrige bruges Opdater efterkrav. Når der er valgt en konto i Fragtindstillinger, registreres en udbetaling som en betaling på salget. Fragtgebyrer kan gemmes som en udgift, når en pakke er afsluttet.',
'Cr_Guide_T_Returns' => 'Returnerede pakker',
'Cr_Guide_B_Returns' => 'Som standard venter en returneret pakke i Fragtforsendelser under Returer til gennemgang. Læg på lager opretter en salgsretur for hele ordren og lægger varerne tilbage på lager; Afvis lægger intet tilbage, til beskadigede eller bortkomne pakker. Fragtindstillinger kan i stedet lægge varerne på lager automatisk.',
'Cr_Guide_T_Customers' => 'Kundebeskeder og sporingsside',
'Cr_Guide_B_Customers' => 'Kundenotifikationer i Fragtindstillinger sender SMS, e-mail eller WhatsApp ved de statusser, du markerer, hver én gang pr. pakke, med din egen tekst. Sporingssiden i din webbutik lader kunderne følge en pakke med sporingsnummer eller med ordrenummer og telefonnummer. Kunder, der ofte returnerer pakker, får et returrisiko-mærke, når du booker.',
'Cr_Guide_T_Labels' => 'Etiketter',
'Cr_Guide_B_Labels' => 'Udskriv etiket giver fragtfirmaets egen etiket, når det udsteder en (en PDF, et link eller et billede), ellers en Stocky-etiket med sporingsstregkoden og beløbet, der skal opkræves. Tillad pop op-vinduer for dette websted for at udskrive. DHL, FedEx og UPS udleverer kun deres etiket én gang, ved booking, og Stocky gemmer den til genudskrivning.',
'Cr_Guide_T_Faq' => 'Fejlfinding',
'Cr_Guide_Q_Test' => 'Test forbindelse fejler',
'Cr_Guide_A_Test' => 'Testnøgler hører til Testtilstand og live-nøgler til Live; de er forskellige. Åbn Fragtlog, og læs fragtfirmaets svar for at se den præcise årsag.',
'Cr_Guide_Q_City' => 'Fragtfirmaet afviser byen eller adressen',
'Cr_Guide_A_City' => 'Vælg byen fra fragtfirmaets byliste i bookingformularen; fragtfirmaer accepterer kun deres egne navne. Fragtfirmaer, der arbejder med postadresser, skal også have stat/region, postnummer og landekode på to bogstaver.',
'Cr_Guide_Q_Webhook' => 'Statusser ændrer sig ikke af sig selv',
'Cr_Guide_A_Webhook' => 'For fragtfirmaer, der sender opdateringer, skal du kontrollere, at webhook-URL\'en er registreret hos fragtfirmaet: Fragtlog viser alle modtagne opdateringer, eller hvorfor en blev afvist (for eksempel en forkert hemmelighed). Andre fragtfirmaer tjekkes efter tidsplanen i Fragtindstillinger, og Tjek status nu spørger med det samme.',
'Cr_Guide_Q_Stuck' => 'En forsendelse viser en fejl ved statustjek',
'Cr_Guide_A_Stuck' => 'Fragtfirmaet afviste de seneste tjek; årsagen står på forsendelsen og i Fragtlog. Efter gentagne fejl tjekkes en forsendelse ikke længere automatisk: ret årsagen, og brug derefter Tjek status nu.',
'Cr_Guide_Q_Label' => 'Intet åbner, når en etiket udskrives',
'Cr_Guide_A_Label' => 'Din browser blokerede pop op-vinduet. Tillad pop op-vinduer for dette websted, og prøv igen.',
'Cr_Guide_Q_Cod' => 'En efterkravsudbetaling blev ikke registreret på salget',
'Cr_Guide_A_Cod' => 'I Fragtindstillinger kræver efterkrav, at kontakten er slået til, og at der er valgt en konto. Uden en konto markeres udbetalinger kun som udbetalt.',
