'Tfa_Guide_Codes_Title' => 'Gem gendannelseskoderne',
'Tfa_Guide_Codes_Text' => 'Lige efter opsætningen vises 8 gendannelseskoder én gang. Hver kode erstatter en telefonkode én enkelt gang — ved en mistet, ødelagt eller nulstillet telefon. Download eller kopiér dem, og opbevar dem et sikkert sted, væk fra telefonen.',
'Tfa_Guide_Codes_Note' => 'Ved at løbe tør? "Nye gendannelseskoder" på profilen erstatter hele sættet; de gamle holder op med at virke.',
'Tfa_Guide_Signin_Title' => 'Login',
'Tfa_Guide_Signin_Text' => 'Efter e-mail og adgangskode beder loginsiden om den aktuelle kode fra appen. Koderne skifter hvert 30. sekund, og hver kode virker én gang.',
'Tfa_Guide_Signin_Trust' => 'Hvis "Spørg ikke igen på denne enhed" markeres, springes koden over i den browser i :days dage.',
