'Tfa_Guide_Require_Title' => 'Gør det obligatorisk',
'Tfa_Guide_Require_Text' => 'Slå "Kræv totrinsgodkendelse" til på dette kort, og vælg derefter de roller, der skal bruge det — eller lad listen stå tom for alle brugere. Klik på Send for at gemme.',
'Tfa_Guide_Require_Next' => 'Ingen bliver logget ud. Brugere, der endnu ikke har 2FA, guides gennem opsætningen på loginsiden ved deres næste login, før de kommer ind, og ser deres gendannelseskoder der.',
'Tfa_Guide_Require_Note' => 'Brugere, som det er påkrævet for, kan ikke slå det fra på deres profil.',
'Tfa_Guide_Trust_Title' => 'Betroede enheder',
'Tfa_Guide_Trust_Text' => '"Husk betroede enheder" bestemmer, hvor længe en browser kan springe koden over efter et vellykket login. Vælg "Spørg altid efter en kode" for delte eller offentlige computere som f.eks. en POS i butikken.',
'Tfa_Guide_Trust_Note' => 'Hvis tallet sænkes, forkortes perioden for allerede betroede enheder; når 2FA slås fra eller nulstilles, glemmes de alle.',
'Tfa_Guide_Lost_Title' => 'Mistet telefon og ingen gendannelseskoder',
'Tfa_Guide_Lost_Text' => 'På siden Brugere viser brugere med 2FA "Til" i 2FA-kolonnen. Skjold-knappen under Handlinger nulstiller det: brugeren logger ind med kun adgangskoden og opsætter appen igen (eller bliver bedt om det, hvis det er påkrævet).',
'Tfa_Guide_Lost_Warn' => 'Bekræft, hvem der spørger, før du nulstiller — en nulstilling fjerner den beskyttelse, 2FA giver kontoen.',
'Tfa_Guide_Open_Users' => 'Åbn Brugere',
'Tfa_Guide_Mobile_Title' => 'Mobilapp og API',
'Tfa_Guide_Mobile_Text' => 'Mobilappen og API-token-endpointet beder om den samme kode. Hvis 2FA er påkrævet for en bruger, der endnu ikke har opsat det, skal vedkommende logge ind på webbet én gang for at gøre det.',
'Tfa_Guide_Protect_Title' => 'Indbygget beskyttelse',
