'Tfa_Guide_Protect_2' => 'Hver kode og hver gendannelseskode virker kun én gang.',
'Tfa_Guide_Protect_3' => 'Med "Registrér login-aktivitet" slået til vises forkerte koder i listen Login-aktivitet som "Forkert 2FA-kode".',
'Tfa_Guide_Trouble_Title' => 'Fejlfinding',
'Tfa_Guide_Faq_Clock_Q' => '“Koden er ikke gyldig” med en ny kode',
'Tfa_Guide_Faq_Clock_A' => 'Telefonens ur går sandsynligvis forkert. Koderne afhænger af klokkeslættet: indstil telefonens dato og tid til automatisk (netværkstid), og prøv derefter den næste kode.',
'Tfa_Guide_Faq_Phone_Q' => 'Skift til en ny telefon',
'Tfa_Guide_Faq_Phone_A' => 'Brug enten godkendelsesappens egen overførselsfunktion, eller slå 2FA fra på profilen og til igen med den nye telefon (hvis det er påkrævet, så bed i stedet en administrator om at nulstille det).',
'Tfa_Guide_Faq_Locked_Q' => '“For mange ugyldige koder”',
'Tfa_Guide_Faq_Locked_A' => 'Vent den viste tid (op til 15 minutter), eller få en administrator til at nulstille brugerens 2FA.',
'Tfa_Guide_Faq_Key_Q' => 'Ingen med 2FA kan logge ind efter en serverflytning',
'Tfa_Guide_Faq_Key_A' => '2FA-hemmelighederne er krypteret med APP_KEY i .env-filen. Behold den samme APP_KEY, når appen flyttes eller gendannes; hvis den er ændret, skal en administrator uden 2FA nulstille de berørte brugere.',
