'Tfa_Guide_Customers_Text' => 'Kunder kan også beskytte deres egne konti. Det er valgfrit for hver kunde og gennemtvinges aldrig: slå det til under Butiksindstillinger → Registrering og adgangskontrol (webbutik) og Kundeportal → Portalindstillinger (kundeportal).',
